pub const GENERATED_MARKER: &str = "@generated by codegen";

/// Package-root-relative location of the child delivery runtime.
///
/// This is the ONE authority for where that file lives. The generated wrapper's
/// import specifier and the Rust install-time re-derivation in
/// `drivers::runner::child_addon_digest_for_path` are both built from it, so a
/// relocation cannot leave one site behind. `include_str!` below must repeat the
/// literal (the macro takes no consts); the two are pinned together by
/// `child_addon_digest_for_path_reads_the_runtime_at_the_generated_entry` in
/// tests/runner_child.rs, which runs the production traversal over the real tree.
pub const CHILD_RUNTIME_ENTRY: &str = "child-runtime/child-extension-runtime.ts";

pub const CHILD_RUNTIME_SOURCE: &str =
    include_str!("../../child-runtime/child-extension-runtime.ts");

pub fn emit_all(
    contracts: &Contracts,
    seam: &TableDoc,
    host: &TableDoc,
    pi_rpc: &TableDoc,
    recovery: &str,
) -> Result<Vec<OutputFile>> {
    let (rust, typescript) = emit_rust_typescript(contracts)?;
    let mut outputs = vec![
        file("kernel/src/generated/mod.rs", rust),
        file("src/generated/index.ts", typescript),
        file(
            "src/generated/frame-validation.ts",
            emit_frame_validation(contracts, seam)?,
        ),
        file(
            "src/generated/host-runtime-tables.ts",
            emit_host_runtime_tables(contracts, host)?,
        ),
        file(
            "src/generated/tool-schemas.ts",
            emit_tool_schemas(contracts)?,
        ),
        file("src/generated/child-extension.ts", emit_child_extension()),
        file(
            "src/generated/child-control-bridge.ts",
            emit_child_control_bridge(contracts)?,
        ),
        file(
            "drivers/src/generated/mod.rs",
            format!(
                "// {GENERATED_MARKER}\n\npub mod pi_rpc;\npub mod recovery;\npub mod tables;\n"
            ),
        ),
        file("drivers/src/generated/pi_rpc.rs", emit_pi_rpc(pi_rpc)?),
        file(
            "drivers/src/generated/recovery.rs",
            emit_recovery(recovery)?,
        ),
        file("drivers/src/generated/tables.rs", emit_seam_tables(seam)?),
    ];
    let mut artifacts = contracts.artifacts.clone();
    artifacts.sort_by_key(|artifact| artifact.name.clone());
    for artifact in artifacts {
        if let Some(admits) = &artifact.admits {
            outputs.push(file(
                &format!("generated/prompts/{}.md", artifact.name),
                emit_prompt(&artifact.name, admits),
            ));
        }
    }
    outputs.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(outputs)
}

fn emit_recovery(recovery: &str) -> Result<String> {
    let line = recovery
        .lines()
        .map(str::trim)
        .find_map(|line| line.strip_prefix("terminal_continuation "))
        .ok_or_else(|| Error::input("recovery policy missing terminal_continuation"))?;
    let max_attempts = recovery_u32(line, "max_attempts=")?;
    require(
        max_attempts == 2,
        "terminal_continuation max_attempts drift; expected one nudge (2 attempts)",
    )?;
    for required in [
        "scope=\"agent-run\"",
        "trigger=\"terminal-miss\"",
        "retryable_classes=\"prose-instead-of-terminal empty-stop-no-terminal\"",
        "terminal_classes=\"no-terminal-frame terminal-tool-not-offered multiple-terminals\"",
        "retry_prompt=\"terminal-directive\"",
        "session=\"same-session-id\"",
        "exhaustion=\"fail-loud\"",
    ] {
        require(
            line.contains(required),
            format!("terminal_continuation missing {required}"),
        )?;
    }
    Ok(format!(
        "// {GENERATED_MARKER}\n\npub const MAX_TERMINAL_ATTEMPTS: u32 = {max_attempts};\n"
    ))
}

fn recovery_u32(line: &str, key: &str) -> Result<u32> {
    let start = line
        .find(key)
        .ok_or_else(|| Error::input(format!("terminal_continuation missing {key}")))?
        + key.len();
    let rest = &line[start..];
    let end = rest
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(rest.len());
    rest[..end]
        .parse::<u32>()
        .map_err(|_| Error::input(format!("terminal_continuation {key} is not a number")))
}

fn emit_pi_rpc(pi: &TableDoc) -> Result<String> {
    validate_pi_rpc(pi)?;
    let commands = rows(pi, "command");
    let mut payloads = Vec::<FieldSpec>::new();
    for row in &commands {
        for field in field(row.string("payload")?)? {
            if !payloads.iter().any(|old| old.rust == field.rust) {
                payloads.push(field);
            }
        }
    }
    let mut out = format!(
        "// {GENERATED_MARKER}\n\nuse serde::{{Deserialize, Serialize}};\nuse serde_json::Value;\n\n"
    );
    emit_limits(&mut out, pi)?;
    emit_env(&mut out, pi);
    emit_command_rows(&mut out, &commands)?;
    emit_launch(&mut out, pi)?;
    emit_order_rows(&mut out, pi)?;
    emit_rpc_command(&mut out, &commands, &payloads)?;
    emit_wire_enum(&mut out, pi, "RpcCommandKind", "pub", true)?;
    emit_domain_types(&mut out, pi)?;
    emit_wire_records(&mut out, pi)?;
    out.push_str("// EventOrder rows are interpreted by counted runner code.\n");
    Ok(out)
}

macro_rules! pi_rpc_emitter {($($t:tt)*)=>{$($t)*};}
pi_rpc_emitter! { #[derive(Clone)] struct FieldSpec { wire: String, rust: String, ty: String, mode: String, } fn rows<'a>(doc: &'a TableDoc, table: &str) -> Vec<&'a TableRow> { doc.rows.iter().filter(|row| row.table == table).collect() } fn validate_pi_rpc(pi: &TableDoc) -> Result<()> { for (table, count) in [ ("command", 8), ("wire_enum", 4), ("wire_variant", 14), ("wire_record", 14), ("event", 23), ("launch_flag", 13), ("env_deny", 12), ("size_limit", 2), ("state", 9), ("order_event", 16), ("transition", 24), ("forbidden", 2), ] { require( rows(pi, table).len() == count, format!("pi-rpc {table} row drift"), )?; } let commands = keyset(pi, "command"); let enums = keyset(pi, "wire_enum"); let records = keyset(pi, "wire_record"); let events = keyset(pi, "order_event"); let states = keyset(pi, "state"); let serde = rows(pi, "command") .iter() .map(|row| row.string("serde")) .collect::<Result<Vec<_>>>()?; unique(serde.into_iter(), "pi-rpc command serde")?; for row in rows(pi, "command") { require( row.string("constructor")? == row.key, format!("pi-rpc command constructor drift at line {}", row.line), )?; require( row.bool("request_id")?, format!("pi-rpc command without request id at line {}", row.line), )?; require( row.string("variant")? == variant_name(&row.key), format!("pi-rpc command variant drift at line {}", row.line), )?; let _ = field(row.string("payload")?)?; } for row in rows(pi, "wire_variant") { require( contains_key(&enums, row.string("enum")?), format!("pi-rpc wire_variant FK drift at line {}", row.line), )?; } for row in rows(pi, "event") { let record = row.string("record")?; require( record.is_empty() || contains_key(&records, record), format!("pi-rpc event record FK drift at line {}", row.line), )?; require( contains_key(&events, row.string("order")?), format!("pi-rpc event order FK drift at line {}", row.line), )?; } let mut previous = 0; for row in rows(pi, "launch_flag") { let order = integer(row, "order")?; require( order > previous, format!("pi-rpc launch_flag order drift at line {}", row.line), )?; previous = order; require( matches!(row.string("kind")?, "bare" | "value" | "optional-addon"), format!("pi-rpc launch_flag kind drift at line {}", row.line), )?; } for row in rows(pi, "env_deny") { require( row.key.bytes().all(|b| b.is_ascii_uppercase() || b == b'_'), format!("pi-rpc malformed env deny at line {}", row.line), )?; } for need in [ "OPENAI_API_KEY", "ANTHROPIC_API_KEY", "OPENROUTER_API_KEY", "PI_API_KEY", "AUTOPILOT_CONTROL_SOCK", "AUTOPILOT_CONTROL_TOKEN", "AUTOPILOT_CONTROL_RUN_ID", "AUTOPILOT_CONTROL_ASSIGNMENT", "AUTOPILOT_CONTROL_ATTEMPT", ] { require( contains_key(&keyset(pi, "env_deny"), need), format!("pi-rpc missing env deny {need}"), )?; } require( limit(pi, "terminal")? == 4_194_304 && limit(pi, "entry_appended")? == 16_384, "pi-rpc size_limit drift", )?; let mut pairs = Vec::new(); for row in rows(pi, "transition") { require( contains_key(&states, row.string("from")?) && contains_key(&states, row.string("to")?) && contains_key(&events, row.string("event")?), format!("pi-rpc transition FK drift at line {}", row.line), )?; pairs.push(format!("{}:{}", row.string("from")?, row.string("event")?)); } unique(pairs.iter().map(String::as_str), "pi-rpc transition")?; for row in rows(pi, "forbidden") { if let Some(from) = row.opt_string("from")? { require( contains_key(&states, from), format!("pi-rpc forbidden state FK drift at line {}", row.line), )?; } let event = row.string("event")?; require( event == "*" || contains_key(&events, event), format!("pi-rpc forbidden event FK drift at line {}", row.line), )?; } require( commands == keyset(pi, "wire_variant") .into_iter() .filter_map(|key| key.strip_prefix("RpcCommandKind:").map(str::to_owned)) .collect::<Vec<_>>(), "pi-rpc command/wire coverage drift", )?; Ok(()) } fn keyset(doc: &TableDoc, table: &str) -> Vec<String> { rows(doc, table).iter().map(|row| row.key.clone()).collect() } fn field(text: &str) -> Result<Vec<FieldSpec>> { if text.is_empty() { return Ok(Vec::new()); } text.split('|') .map(|part| { let pieces = part.split(':').collect::<Vec<_>>(); require( (2..=4).contains(&pieces.len()), format!("bad pi-rpc field spec `{part}`"), )?; let (wire, rust, ty, mode) = if pieces.len() == 4 { (pieces[0], pieces[1], pieces[2], pieces[3]) } else { ( pieces.get(2).copied().unwrap_or(pieces[0]), pieces[0], pieces[1], "required", ) }; Ok(FieldSpec { wire: wire.to_owned(), rust: rust.to_owned(), ty: ty.to_owned(), mode: mode.to_owned(), }) }) .collect() } fn emit_limits(out: &mut String, pi: &TableDoc) -> Result<()> { out.push_str(&format!("pub const DEFAULT_MAX_TERMINAL_BYTES: usize = {};\npub const MAX_ENTRY_APPENDED_BYTES: usize = {};\n", rust_usize(limit(pi, "terminal")?), rust_usize(limit(pi, "entry_appended")?))); Ok(()) } fn emit_env(out: &mut String, pi: &TableDoc) { out.push_str("pub const ENV_DENY: &[&str] = &[\n"); for row in rows(pi, "env_deny") { out.push_str(&format!("    \"{}\",\n", escape_rust_string(&row.key))); } out.push_str("];\n\n"); } fn emit_command_rows(out: &mut String, commands: &[&TableRow]) -> Result<()> { out.push_str("pub struct CommandRow {\n    pub name: &'static str,\n    pub serde: &'static str,\n    pub variant: &'static str,\n    pub payload: &'static str,\n}\npub const COMMANDS: &[CommandRow] = &[\n"); for row in commands { out.push_str(&format!("    CommandRow {{\n        name: \"{}\",\n        serde: \"{}\",\n        variant: \"{}\",\n        payload: \"{}\",\n    }},\n", escape_rust_string(&row.key), escape_rust_string(row.string("serde")?), escape_rust_string(row.string("variant")?), escape_rust_string(row.string("payload")?))); } out.push_str("];\n\n"); Ok(()) } fn emit_launch(out: &mut String, pi: &TableDoc) -> Result<()> { out.push_str("#[derive(Debug, Clone, Copy, Eq, PartialEq)]\npub enum LaunchFlagKind {\n    Bare,\n    Value,\n    OptionalAddon,\n}\npub struct LaunchFlagRow {\n    pub id: &'static str,\n    pub kind: LaunchFlagKind,\n    pub name: &'static str,\n    pub value: Option<&'static str>,\n    pub identity_token: &'static str,\n}\npub const LAUNCH_FLAGS: &[LaunchFlagRow] = &[\n"); for row in rows(pi, "launch_flag") { out.push_str(&format!("    LaunchFlagRow {{\n        id: \"{}\",\n        kind: LaunchFlagKind::{},\n        name: \"{}\",\n        value: {},\n        identity_token: \"{}\",\n    }},\n", escape_rust_string(&row.key), type_name(row.string("kind")?), escape_rust_string(row.string("name")?), opt(row.opt_string("value")?), escape_rust_string(row.string("identity_token")?))); } out.push_str("];\n\n"); Ok(()) } fn emit_order_rows(out: &mut String, pi: &TableDoc) -> Result<()> { out.push_str("pub struct OrderStateRow {\n    pub name: &'static str,\n    pub terminal_ok: bool,\n}\npub const ORDER_STATES: &[OrderStateRow] = &[\n"); for row in rows(pi, "state") { out.push_str(&format!( "    OrderStateRow {{\n        name: \"{}\",\n        terminal_ok: {},\n    }},\n", escape_rust_string(&row.key), row.opt_bool("terminal_ok")?.unwrap_or(false) )); } out.push_str("];\npub struct OrderTransitionRow {\n    pub from: &'static str,\n    pub event: &'static str,\n    pub to: &'static str,\n}\npub const ORDER_TRANSITIONS: &[OrderTransitionRow] = &[\n"); for row in rows(pi, "transition") { out.push_str(&format!("    OrderTransitionRow {{\n        from: \"{}\",\n        event: \"{}\",\n        to: \"{}\",\n    }},\n", row.string("from")?, row.string("event")?, row.string("to")?)); } out.push_str("];\npub struct ForbiddenOrderRow {\n    pub from: Option<&'static str>,\n    pub event: &'static str,\n    pub reason: &'static str,\n}\npub const FORBIDDEN_ORDERS: &[ForbiddenOrderRow] = &[\n"); for row in rows(pi, "forbidden") { out.push_str(&format!("    ForbiddenOrderRow {{\n        from: {},\n        event: \"{}\",\n        reason: \"{}\",\n    }},\n", opt(row.opt_string("from")?), row.string("event")?, row.string("reason")?)); } out.push_str("];\n\n"); Ok(()) } fn emit_rpc_command( out: &mut String, commands: &[&TableRow], payloads: &[FieldSpec], ) -> Result<()> { out.push_str("#[derive(Debug, Clone, Eq, PartialEq, Serialize)]\npub struct RpcCommand {\n    pub id: String,\n    #[serde(rename = \"type\")]\n    pub command: RpcCommandKind,\n"); for field in payloads { out.push_str(&format!( "{}    pub {}: Option<{}>,\n", serde_attrs(field, true), field.rust, field.ty )); } out.push_str("}\nimpl RpcCommand {\n"); for row in commands { let fields = field(row.string("payload")?)?; let args = fields .iter() .map(|f| format!(", {}: impl Into<{}>", f.rust, f.ty)) .collect::<String>(); out.push_str(&format!("    #[must_use]\n    pub fn {}(id: impl Into<String>{args}) -> Self {{\n        Self {{\n            id: id.into(),\n            command: RpcCommandKind::{},\n", row.string("constructor")?, row.string("variant")?)); for field in payloads { let value = fields .iter() .find(|f| f.rust == field.rust) .map_or_else(|| "None".to_owned(), |f| format!("Some({}.into())", f.rust)); out.push_str(&format!("            {}: {value},\n", field.rust)); } out.push_str("        }\n    }\n"); } out.push_str("}\n\n"); Ok(()) } fn emit_wire_enum( out: &mut String, pi: &TableDoc, name: &str, vis: &str, as_str: bool, ) -> Result<()> { let row = rows(pi, "wire_enum") .into_iter() .find(|row| row.key == name) .ok_or_else(|| Error::input(format!("missing wire_enum {name}")))?; let tag = row.string("serde_tag")?; out.push_str(&format!( "#[derive(Debug, Clone, Copy, Eq, PartialEq, Serialize, Deserialize)]\n{} enum {name} {{\n", vis )); for v in rows(pi, "wire_variant") .into_iter() .filter(|v| v.string("enum").is_ok_and(|e| e == name)) { if v.string("serde")? == "other" { out.push_str("    #[serde(other)]\n"); } else { out.push_str(&format!( "    #[serde(rename = \"{}\")]\n", escape_rust_string(v.string("serde")?) )); } out.push_str(&format!("    {},\n", v.string("variant")?)); } out.push_str("}\n"); if as_str { out.push_str(&format!("impl {name} {{\n    #[must_use]\n    pub fn as_str(self) -> &'static str {{\n        match self {{\n")); for v in rows(pi, "wire_variant") .into_iter() .filter(|v| v.string("enum").is_ok_and(|e| e == name)) { out.push_str(&format!( "            Self::{} => \"{}\",\n", v.string("variant")?, escape_rust_string(v.string("serde")?) )); } out.push_str("        }\n    }\n}\n"); }
if !tag.is_empty() { out.push('\n'); } Ok(()) } fn emit_domain_types(out: &mut String, pi: &TableDoc) -> Result<()> { out.push_str("#[derive(Debug, Clone, Eq, PartialEq)]\npub enum RpcFrame {\n    Response(RpcResponse),\n    Event(RpcEvent),\n}\n#[derive(Debug, Clone, Eq, PartialEq)]\npub struct RpcResponse {\n    pub id: String,\n    pub command: RpcCommandKind,\n    pub success: bool,\n    pub queued_not_delivered: bool,\n    pub data: Option<String>,\n    pub error: Option<String>,\n}\n#[derive(Debug, Clone, Eq, PartialEq)]\npub struct AppendedEntry {\n    pub id: String,\n    pub custom_type: String,\n    pub data: Value,\n}\n#[derive(Debug, Clone, Eq, PartialEq, Serialize, Deserialize)]\n#[serde(deny_unknown_fields)]\npub struct ToolCarrierDetails {\n    pub profile_id: String,\n    pub tool_name: String,\n    pub boundary_id: String,\n    pub result_contract: String,\n    pub schema_digest: String,\n    pub binding: String,\n    pub payload: Value,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    pub delivery_policy_denials: Option<Value>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    pub approved_command_executions: Option<Value>,\n}\n#[derive(Debug, Clone, Eq, PartialEq)]\npub struct TerminalMessage {\n    pub role: String,\n    pub tool_call_id: Option<String>,\n    pub tool_name: Option<String>,\n    pub provider: Option<String>,\n    pub model: Option<String>,\n    pub stop_reason: Option<String>,\n    pub text: Option<String>,\n    pub error_message: Option<String>,\n    pub details: Option<Value>,\n}\n"); emit_wire_enum(out, pi, "CompactionReason", "pub", false)?; out.push_str("#[derive(Debug, Clone, Eq, PartialEq)]\npub enum RpcEvent {\n"); for row in rows(pi, "event") { emit_event_variant(out, row)?; } out.push_str("}\n\n"); Ok(()) } fn emit_event_variant(out: &mut String, row: &TableRow) -> Result<()> { let variant = row.string("variant")?; match row.string("record")? { "" => out.push_str(&format!("    {variant},\n")), "AgentEnd" => out.push_str(&format!("    {variant} {{\n        will_retry: bool,\n    }},\n")), "MessageEnd" => out.push_str(&format!("    {variant} {{\n        message: TerminalMessage,\n    }},\n")), "ToolExecutionEnd" => out.push_str(&format!("    {variant} {{\n        tool_call_id: String,\n        tool_name: String,\n        details: Option<Value>,\n        is_error: bool,\n        terminate: bool,\n    }},\n")), "EntryAppendedRecord" => out.push_str(&format!("    {variant} {{\n        entry: AppendedEntry,\n    }},\n")), "QueueUpdate" => out.push_str(&format!("    {variant} {{\n        steering: usize,\n        follow_up: usize,\n    }},\n")), "CompactionStart" => out.push_str(&format!("    {variant} {{\n        reason: CompactionReason,\n    }},\n")), "CompactionEnd" => out.push_str(&format!("    {variant} {{\n        reason: CompactionReason,\n        aborted: bool,\n        will_retry: bool,\n    }},\n")), "AutoRetryEnd" => out.push_str(&format!("    {variant} {{\n        success: bool,\n    }},\n")), other => return Err(Error::input(format!("pi-rpc event conversion missing for {other}"))), } Ok(()) } fn emit_wire_records(out: &mut String, pi: &TableDoc) -> Result<()> { emit_wire_enum(out, pi, "CustomEntryKind", "pub(crate)", false)?; let skip = ["MessageContentText"]; for row in rows(pi, "wire_record") { if skip.contains(&row.key.as_str()) { continue; } emit_record(out, row)?; if row.key == "AgentMessage" { out.push_str("impl AgentMessage {\n    pub(crate) fn into_terminal(self) -> TerminalMessage {\n        TerminalMessage {\n            role: self.role,\n            tool_call_id: self.tool_call_id,\n            tool_name: self.tool_name,\n            provider: self.provider,\n            model: self.model,\n            stop_reason: self.stop_reason,\n            text: self.content.map(extract_text),\n            error_message: self.error_message,\n            details: self.details,\n        }\n    }\n}\n"); emit_message_content(out, pi)?; out.push_str("fn extract_text(content: Vec<MessageContent>) -> String {\n    content\n        .into_iter()\n        .filter_map(|item| match item {\n            MessageContent::Text { text } => Some(text),\n            MessageContent::Other => None,\n        })\n        .collect()\n}\n"); } } Ok(()) } fn emit_record(out: &mut String, row: &TableRow) -> Result<()> { out.push_str(&format!( "#[derive(Deserialize)]\npub(crate) struct {} {{\n", row.key )); for field in field(row.string("fields")?)? { out.push_str(&format!( "{}    pub {}: {},\n", serde_attrs(&field, false), field.rust, rust_field_ty(&field) )); } out.push_str("}\n"); Ok(()) } fn emit_message_content(out: &mut String, pi: &TableDoc) -> Result<()> { let tag = rows(pi, "wire_enum") .into_iter() .find(|row| row.key == "MessageContent") .ok_or_else(|| Error::input("missing MessageContent"))? .string("serde_tag")?; out.push_str(&format!( "#[derive(Deserialize)]\n#[serde(tag = \"{}\")]\npub(crate) enum MessageContent {{\n", escape_rust_string(tag) )); for row in rows(pi, "wire_variant") .into_iter() .filter(|row| row.string("enum").is_ok_and(|e| e == "MessageContent")) { if row.string("serde")? == "other" { out.push_str("    #[serde(other)]\n    Other,\n"); } else { out.push_str(&format!( "    #[serde(rename = \"{}\")]\n    {} {{ text: String }},\n", escape_rust_string(row.string("serde")?), row.string("variant")? )); } } out.push_str("}\n"); Ok(()) } fn serde_attrs(field: &FieldSpec, command_payload: bool) -> String { let mut attrs = String::new(); if field.wire != field.rust { attrs.push_str(&format!( "    #[serde(rename = \"{}\"", escape_rust_string(&field.wire) )); } else if matches!(field.mode.as_str(), "default" | "default_optional") || command_payload { attrs.push_str("    #[serde("); }
if !attrs.is_empty() { if matches!(field.mode.as_str(), "default" | "default_optional") { attrs.push_str(if attrs.ends_with('(') { "default" } else { ", default" }); }
if command_payload { attrs.push_str(if attrs.ends_with('(') { "skip_serializing_if = \"Option::is_none\"" } else { ", skip_serializing_if = \"Option::is_none\"" }); } attrs.push_str(")]\n"); } attrs } fn rust_field_ty(field: &FieldSpec) -> String { if matches!(field.mode.as_str(), "optional" | "default_optional") { format!("Option<{}>", field.ty) } else { field.ty.clone() } } fn opt(value: Option<&str>) -> String { value.map_or_else( || "None".to_owned(), |v| format!("Some(\"{}\")", escape_rust_string(v)), ) } fn limit(pi: &TableDoc, key: &str) -> Result<i64> { rows(pi, "size_limit") .into_iter() .find(|row| row.key == key) .ok_or_else(|| Error::input(format!("missing size_limit {key}"))) .and_then(|row| integer(row, "bytes")) } fn integer(row: &TableRow, key: &str) -> Result<i64> { row.props .iter() .find(|prop| prop.0 == key) .and_then(|prop| prop.1.as_integer()) .and_then(|value| i64::try_from(value).ok()) .ok_or_else(|| Error::input(format!("`{key}` must be integer at line {}", row.line))) } fn contains_key(keys: &[String], needle: &str) -> bool { keys.iter().any(|key| key == needle) } fn rust_usize(value: i64) -> String { value .to_string() .as_bytes() .rchunks(3) .rev() .map(std::str::from_utf8) .collect::<std::result::Result<Vec<_>, _>>() .unwrap() .join("_") } fn unique<'a>(values: impl Iterator<Item = &'a str>, label: &str) -> Result<()> { let mut seen = Vec::new(); for value in values { require( !seen.contains(&value), format!("duplicate {label} `{value}`"), )?; seen.push(value); } Ok(()) } fn require(ok: bool, message: impl Into<String>) -> Result<()> { if ok { Ok(()) } else { Err(Error::input(message.into())) } } }
fn emit_seam_tables(seam: &TableDoc) -> Result<String> {
    let (mut host, mut core, mut imports, mut variants, mut arms) =
        (Vec::new(), Vec::new(), Vec::new(), Vec::new(), Vec::new());
    for row in &seam.rows {
        let (kind, direction, posture, payload, adapter, effect) = seam_fields(row)?;
        let literal = row_literal(kind, direction, posture, payload, adapter, effect);
        if direction == "host-to-core" {
            host.push(literal);
            if posture == "supported" {
                imports.push(payload.to_owned());
                let escaped_kind = escape_rust_string(kind);
                let variant = type_name(kind);
                variants.push(format!("    {variant}({payload}),"));
                arms.push(format!(
                    "        \"{escaped_kind}\" => decode::<{payload}>(\"{escaped_kind}\", payload)\n            .map(HostToCoreRoute::{variant}),"
                ));
            }
        } else {
            core.push(literal);
        }
    }
    imports.sort();
    imports.dedup();
    let imports = imports
        .chunks(3)
        .map(|chunk| format!("    {},", chunk.join(", ")))
        .collect::<Vec<_>>()
        .join("\n");
    Ok(format!(
        "// {GENERATED_MARKER}\n\nuse kernel::generated::{{\n{imports}\n}};\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum SeamDirection {{\n    HostToCore,\n    CoreToHost,\n}}\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum SeamPosture {{\n    Supported,\n    Unsupported,\n}}\npub struct SeamRouteRow {{\n    pub kind: &'static str,\n    pub direction: SeamDirection,\n    pub posture: SeamPosture,\n    pub payload: &'static str,\n    pub adapter: &'static str,\n    pub effect: &'static str,\n}}\npub enum HostToCoreRoute {{\n{}\n}}\npub enum SeamAdmissionError {{\n    Unknown(String),\n    Unsupported(&'static SeamRouteRow),\n    Payload {{ kind: &'static str, error: String }},\n}}\npub static HOST_TO_CORE_ROUTES: &[SeamRouteRow] = &[\n{}\n];\npub static CORE_TO_HOST_EFFECTS: &[SeamRouteRow] = &[\n{}\n];\npub fn host_to_core_route(kind: &str) -> Option<&'static SeamRouteRow> {{\n    HOST_TO_CORE_ROUTES.iter().find(|row| row.kind == kind)\n}}\npub fn core_to_host_effect(kind: &str) -> Option<&'static SeamRouteRow> {{\n    CORE_TO_HOST_EFFECTS.iter().find(|row| row.kind == kind)\n}}\npub fn admit_host_to_core(\n    kind: &str,\n    payload: serde_json::Value,\n) -> Result<HostToCoreRoute, SeamAdmissionError> {{\n    let row =\n        host_to_core_route(kind).ok_or_else(|| SeamAdmissionError::Unknown(kind.to_owned()))?;\n    if row.posture == SeamPosture::Unsupported {{\n        return Err(SeamAdmissionError::Unsupported(row));\n    }}\n    match row.kind {{\n{}\n        other => Err(SeamAdmissionError::Unknown(other.to_owned())),\n    }}\n}}\nfn decode<T: serde::de::DeserializeOwned>(\n    kind: &'static str,\n    payload: serde_json::Value,\n) -> Result<T, SeamAdmissionError> {{\n    serde_json::from_value::<T>(payload).map_err(|error| SeamAdmissionError::Payload {{\n        kind,\n        error: error.to_string(),\n    }})\n}}\n",
        variants.join("\n"),
        host.join("\n"),
        core.join("\n"),
        arms.join("\n"),
    ))
}

fn seam_fields(row: &TableRow) -> Result<(&str, &str, &str, &str, &str, &str)> {
    Ok((
        row.string("kind")?,
        row.string("direction")?,
        row.string("posture")?,
        row.string("payload")?,
        row.string("adapter")?,
        row.string("effect")?,
    ))
}

fn row_literal(
    kind: &str,
    direction: &str,
    posture: &str,
    payload: &str,
    adapter: &str,
    effect: &str,
) -> String {
    format!(
        "    SeamRouteRow {{\n        kind: \"{}\",\n        direction: SeamDirection::{},\n        posture: SeamPosture::{},\n        payload: \"{}\",\n        adapter: \"{}\",\n        effect: \"{}\",\n    }},",
        escape_rust_string(kind),
        if direction == "host-to-core" { "HostToCore" } else { "CoreToHost" },
        if posture == "supported" { "Supported" } else { "Unsupported" },
        escape_rust_string(payload),
        escape_rust_string(adapter),
        escape_rust_string(effect),
    )
}
macro_rules! host_emitter {($($t:tt)*)=>{$($t)*};}
host_emitter! { fn emit_host_runtime_tables(contracts:&Contracts,host:&TableDoc)->Result<String>{let rows=|t:&str|host.rows.iter().filter(move|r|r.table==t).collect::<Vec<_>>();let commands=rows("command").iter().map(|r|Ok(json!({"name":r.key,"activation":r.string("activation")?,"frame":r.string("frame")?,"description":r.string("description")?,"adapter":r.string("adapter")?,"payload":r.string("payload")?,"fields":payload_fields(contracts,r.string("payload")?)}))).collect::<Result<Vec<_>>>()?;let protocol=json!({"request":chan(&rows("background_channel"),"request")?,"response":chan(&rows("background_channel"),"response")?,"terminal":chan(&rows("background_channel"),"terminal")?});let statuses=rows("background_status").iter().map(|r|json!({"name":r.key,"terminal":r.bool("terminal").unwrap_or(false)})).collect::<Vec<_>>();let caps=rows("background_capability").iter().map(|r|Ok(format!("  {}: {},",quote_ts_key(&r.key),ts_default(r)?))).collect::<Result<Vec<_>>>()?.join("\n");let effects=rows("effect").iter().map(|r|json!({"kind":r.key,"operator_level_default":r.string("operator_level_default").unwrap_or("info"),"fail_closed":r.bool("fail_closed").unwrap_or(false),"acknowledge":r.bool("acknowledge").unwrap_or(false),"max_items":r.props.iter().find(|p|p.0=="max_items").and_then(|p|p.1.as_integer())})).collect::<Vec<_>>();let act=&rows("activation_record")[0];Ok(format!("// {GENERATED_MARKER}\n\nexport const HOST_COMMANDS = {} as const;\nexport const ACTIVATING_COMMANDS = HOST_COMMANDS.filter((row) => row.activation === \"activating\").map((row) => row.name);\nexport const OPERATING_COMMANDS = HOST_COMMANDS.filter((row) => row.activation === \"operating\").map((row) => row.name);\nexport const BACKGROUND_PROTOCOL = {} as const;\nexport const BACKGROUND_OPERATIONS = {} as const;\nexport const BACKGROUND_STATUSES = {} as const;\nexport const UNAVAILABLE_BACKGROUND_CAPABILITIES = {{\n{}\n}} as const;\nexport const HOST_ENV_DENY = {} as const;\nexport const HOST_EFFECTS = {} as const;\nexport const ACTIVATION_RECORD = {{ schema_version: \"{}\", fields: {} as const }} as const;\n",json_string(&json!(commands),"host commands")?,json_string(&protocol,"host protocol")?,json_string(&json!(rows("background_operation").iter().map(|r|r.key.as_str()).collect::<Vec<_>>()),"host ops")?,json_string(&json!(statuses),"host statuses")?,caps,json_string(&json!(rows("env_deny").iter().map(|r|r.key.as_str()).collect::<Vec<_>>()),"host env")?,json_string(&json!(effects),"host effects")?,escape_ts_string(&act.key),json_string(&json!(act.string("fields")?.split('|').collect::<Vec<_>>()),"activation fields")?))} fn payload_fields(contracts:&Contracts,payload:&str)->Vec<JsonValue>{contracts.frames.iter().find(|f|frame_type_name(f)==payload).map(|f|f.items.iter().filter(|i|i.kind==ItemKind::Field).map(|i|json!({"name":i.name,"type":i.type_id,"required":i.required,"nullable":i.nullable})).collect()).unwrap_or_default()} fn chan(rows:&[&TableRow],key:&str)->Result<JsonValue>{let r=rows.iter().find(|r|r.key==key).ok_or_else(||Error::input(format!("missing channel {key}")))?;Ok(json!({"channel":r.string("channel")?,"schema":r.string("schema")?}))} fn ts_default(row:&TableRow)->Result<String>{let v=row.props.iter().find(|p|p.0=="default").map(|p|&p.1).ok_or_else(||Error::input("missing capability default"))?;Ok(if let Some(b)=v.as_bool(){b.to_string()}else if let Some(n)=v.as_integer(){n.to_string()}else{return Err(Error::input(format!("bad capability default at line {}",row.line)));})} }

fn emit_frame_validation(contracts: &Contracts, seam: &TableDoc) -> Result<String> {
    let mut shapes = BTreeMap::new();
    let records = record_items_by_name(contracts);
    let artifacts = contracts
        .artifacts
        .iter()
        .map(|artifact| artifact.name.clone())
        .collect::<std::collections::BTreeSet<_>>();
    for artifact in &contracts.artifacts {
        if artifact.name != "background_action" {
            continue;
        }
        let name = type_name(&artifact.name);
        collect_shape(&mut shapes, &name, &artifact.items, &name, &records, &artifacts)?;
    }
    for frame in &contracts.frames {
        if frame.direction != "core-to-host" {
            continue;
        }
        let name = frame_type_name(frame);
        collect_shape(&mut shapes, &name, &frame.items, &name, &records, &artifacts)?;
    }
    let enums = contracts
        .enums
        .iter()
        .map(|entry| (entry.name.clone(), json!(entry.values)))
        .collect::<BTreeMap<_, _>>();
    let mut routes = BTreeMap::new();
    for row in &seam.rows {
        if !row
            .string("direction")
            .is_ok_and(|direction| direction == "core-to-host")
        {
            continue;
        }
        routes.insert(row.string("kind")?.to_owned(), route_descriptor(row)?);
    }
    let descriptors = json!({
        "shapes": shapes,
        "enums": enums,
        "routes": routes,
        "list_constraints": [
            {
                "route": "spawn-wave",
                "field": "actions",
                "min": 1,
                "max": 64,
                "unique_fields": ["action_id", "assignment_id"],
            },
        ],
    });
    let descriptors = pretty_json(&descriptors, "frame validation descriptors")?;
    Ok(format!(
        "// {GENERATED_MARKER}\n\n{}\n\nconst FRAME_VALIDATION_DESCRIPTORS = {descriptors} as const;\n\n{}",
        frame_validation_imports(),
        frame_validation_exports()
    ))
}

fn route_descriptor(row: &TableRow) -> Result<JsonValue> {
    Ok(json!({
        "effect": row.string("effect")?, "payload": row.string("payload")?, "posture": row.string("posture")?,
    }))
}

fn frame_validation_imports() -> &'static str {
    r#"import type { BackgroundAction, BackgroundActionBgRun, CoreToHostFrame } from "./index.ts";
import {
  CoreFrameValidationError,
  validateBackgroundActionWithDescriptors,
  validateBgRunDescriptorIdentityWithDescriptors,
  validateCoreToHostFrameWithDescriptors,
} from "../frame-validation-runtime.ts";"#
}

fn frame_validation_exports() -> &'static str {
    r#"export { CoreFrameValidationError };

export function validateCoreToHostFrame(value: unknown): CoreToHostFrame {
  return validateCoreToHostFrameWithDescriptors(
    FRAME_VALIDATION_DESCRIPTORS,
    value,
  ) as CoreToHostFrame;
}

export function validateBackgroundAction(value: unknown): BackgroundAction {
  return validateBackgroundActionWithDescriptors(
    FRAME_VALIDATION_DESCRIPTORS,
    value,
  ) as BackgroundAction;
}

export function validateBgRunDescriptorIdentity<T extends BackgroundActionBgRun>(value: T): T {
  validateBgRunDescriptorIdentityWithDescriptors(FRAME_VALIDATION_DESCRIPTORS, value);
  return value;
}
"#
}

fn pretty_json(value: &JsonValue, label: &str) -> Result<String> {
    serde_json::to_string_pretty(value)
        .map_err(|error| Error::input(format!("{label} emit failed: {error}")))
}

fn collect_shape(
    shapes: &mut BTreeMap<String, JsonValue>,
    name: &str,
    items: &[Item],
    prefix: &str,
    records: &BTreeMap<String, Vec<Item>>,
    artifacts: &std::collections::BTreeSet<String>,
) -> Result<()> {
    if shapes.contains_key(name) {
        return Ok(());
    }
    let mut fields = Vec::new();
    for item in items {
        match item.kind {
            ItemKind::Field => {
                let (kind, ty) = value_ref(&item.type_id, records, artifacts);
                fields.push(json!({
                    "name": item.name,
                    "kind": kind,
                    "type": ty,
                    "required": item.required,
                    "nullable": item.nullable,
                }));
            }
            ItemKind::List => {
                let (kind, ty) = value_ref(&item.type_id, records, artifacts);
                fields.push(json!({
                    "name": item.name,
                    "kind": "list",
                    "item_kind": kind,
                    "item_type": ty,
                    "required": item.required,
                    "nullable": item.nullable,
                }));
            }
            ItemKind::Group => {
                let nested = nested_name(prefix, item);
                collect_shape(shapes, &nested, &item.items, &nested, records, artifacts)?;
                fields.push(json!({
                    "name": item.name,
                    "kind": "shape",
                    "type": nested,
                    "required": item.required,
                    "nullable": item.nullable,
                }));
            }
            ItemKind::Record => {}
        }
    }
    shapes.insert(name.to_owned(), json!({ "fields": fields }));
    Ok(())
}

fn value_ref(
    type_id: &str,
    records: &BTreeMap<String, Vec<Item>>,
    artifacts: &std::collections::BTreeSet<String>,
) -> (&'static str, String) {
    if records.contains_key(type_id) || type_id == "background_action" {
        ("shape", type_name(type_id))
    } else if artifacts.contains(type_id) {
        // The Host validator closes the outer frame. Nested artifact unions are
        // already closed Rust/TypeScript protocol types and are broker-consumed.
        ("value", "object".to_owned())
    } else {
        ("value", type_id.to_owned())
    }
}

fn file(path: &str, content: String) -> OutputFile {
    OutputFile {
        path: PathBuf::from(path),
        content,
    }
}

fn emit_rust_typescript(contracts: &Contracts) -> Result<(String, String)> {
    let mut rust = format!(
        "// {GENERATED_MARKER}\n\nuse serde::{{Deserialize, Deserializer, Serialize}};\n\n#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]\n#[serde(transparent)]\npub struct Nullable<T>(pub Option<T>);\n\nfn deserialize_required_nullable<'de, D, T>(deserializer: D) -> Result<Nullable<T>, D::Error>\nwhere\n    D: Deserializer<'de>,\n    T: Deserialize<'de>,\n{{\n    Option::<T>::deserialize(deserializer).map(Nullable)\n}}\n\n"
    );
    let mut ts =
        format!("// {GENERATED_MARKER}\n\nexport type JsonObject = Record<string, unknown>;\n\n");
    for scalar in scalar_newtypes(contracts) {
        let ty = type_name(&scalar);
        rust.push_str("#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]\n#[serde(transparent)]\n");
        rust.push_str(&format!("pub struct {ty}(pub String);\n\n"));
        ts.push_str(&format!("export type {ty} = string;\n"));
    }
    ts.push('\n');
    let mut enums = contracts.enums.clone();
    enums.sort_by_key(|entry| entry.name.clone());
    for entry in &enums {
        let ty = type_name(&entry.name);
        if let Some(doc) = &entry.doc {
            rust.push_str(&rust_doc(doc));
        }
        rust.push_str("#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]\n");
        rust.push_str(&format!("pub enum {ty} {{\n"));
        let mut values = entry.values.clone();
        values.sort();
        for value in values {
            rust.push_str(&format!(
                "    #[serde(rename = \"{}\")]\n    {},\n",
                escape_rust_string(&value),
                variant_name(&value)
            ));
        }
        rust.push_str("}\n\n");
        ts.push_str(&format!(
            "export type {ty} = {};\n",
            entry
                .values
                .iter()
                .map(|v| format!("\"{}\"", escape_ts_string(v)))
                .collect::<Vec<_>>()
                .join(" | ")
        ));
    }
    ts.push('\n');
    let mut artifacts = contracts.artifacts.clone();
    artifacts.sort_by_key(|artifact| artifact.name.clone());
    for artifact in &artifacts {
        if let Some(tag) = &artifact.union_tag {
            emit_tagged_union(
                &mut rust,
                &mut ts,
                &type_name(&artifact.name),
                &artifact.doc,
                tag,
                &artifact.items,
            );
        } else {
            emit_shape_tree(
                &mut rust,
                &mut ts,
                &type_name(&artifact.name),
                &artifact.doc,
                &artifact.items,
                artifact.model_produced && !artifact.submit_tools.iter().any(|tool| tool.closed),
            );
        }
    }
    let mut frame_names = Vec::new();
    let mut frames = contracts.frames.clone();
    frames.sort_by(|left, right| {
        (left.direction.as_str(), left.kind.as_str())
            .cmp(&(right.direction.as_str(), right.kind.as_str()))
    });
    for frame in &frames {
        let name = frame_type_name(frame);
        frame_names.push((frame.direction.clone(), frame.kind.clone(), name.clone()));
        emit_shape_tree(&mut rust, &mut ts, &name, &frame.doc, &frame.items, false);
    }
    emit_constants(&mut rust, contracts, &emit_child_extension());
    emit_submit_rows(&mut rust, contracts)?;
    emit_frame_unions(&mut ts, &frame_names);
    Ok((rust, ts))
}

fn emit_constants(rust: &mut String, contracts: &Contracts, child: &str) {
    rust.push_str(&format!(
        "pub const CONTRACT_SCHEMA: &str = \"{}\";\n",
        escape_rust_string(&contracts.schema)
    ));
    rust.push_str(&format!(
        "pub const CONTRACT_VERSION: u64 = {};\n",
        contracts.version
    ));
    rust.push_str(&format!(
        "pub const CHILD_ADDON_DIGEST: &str =\n    \"{}\";\n\n",
        sha256_hex(format!("{child}\0{CHILD_RUNTIME_SOURCE}").as_bytes())
    ));
    rust.push_str(&format!(
        "pub const CHILD_RUNTIME_ENTRY: &str = \"{}\";\n\n",
        escape_rust_string(CHILD_RUNTIME_ENTRY)
    ));
    let mut admits = BTreeMap::new();
    for artifact in &contracts.artifacts {
        if let Some(text) = &artifact.admits {
            admits.insert(
                artifact.name.clone(),
                (artifact.schema.clone(), text.clone()),
            );
        }
    }
    for (name, (_, text)) in &admits {
        rust.push_str(&format!(
            "pub const {}_ADMITS: &str = \"{}\";\n",
            screaming_name(name),
            escape_rust_string(text)
        ));
    }
    for artifact in &contracts.artifacts {
        if let Some(max_bytes) = artifact.max_bytes {
            rust.push_str(&format!(
                "pub const {}_MAX_BYTES: usize = {};\n",
                screaming_name(&artifact.name),
                max_bytes
            ));
        }
    }
    rust.push_str(&format!(
        "\npub const ADMISSION_CONTRACTS: [(&str, &str, &str); {}] = [\n",
        admits.len()
    ));
    for (name, (schema, text)) in &admits {
        rust.push_str(&format!(
            "    (\n        \"{}\",\n        \"{}\",\n        \"{}\",\n    ),\n",
            escape_rust_string(name),
            escape_rust_string(schema),
            escape_rust_string(text)
        ));
    }
    rust.push_str("];\n");
}

fn emit_submit_rows(rust: &mut String, contracts: &Contracts) -> Result<()> {
    let enums = enum_map(contracts);
    let shapes = schema_items_by_name(contracts);
    let mut submit_rows = Vec::new();
    let mut profile_rows = Vec::new();
    let mut universal_rows = Vec::new();
    for artifact in &contracts.artifacts {
        if artifact.submit_tools.is_empty() {
            continue;
        }
        let schema = json_schema_for_items(&artifact.items, &shapes, &enums, false)?;
        let digest = sha256_hex(json_string(&schema, "tool schema digest")?.as_bytes());
        for tool in &artifact.submit_tools {
            if !tool.universal && artifact.schema.starts_with("planning.") {
                submit_rows.push(format!(
                    "    (\n        \"{}\",\n        \"{}\",\n        \"{}\",\n    ),",
                    escape_rust_string(&tool.name),
                    escape_rust_string(&artifact.schema),
                    digest
                ));
            }
            let parameters = json_schema_for_items(&artifact.items, &shapes, &enums, tool.closed)?;
            let pdigest =
                sha256_hex(json_string(&parameters, "terminal profile digest")?.as_bytes());
            if tool.universal {
                universal_rows.push(format!("    (\n        \"{}\",\n        \"{}\",\n        \"{}\",\n        \"{}\",\n        \"{}\",\n        \"{}\",\n    ),", escape_rust_string(&tool.profile), escape_rust_string(&tool.name), escape_rust_string(&artifact.schema), escape_rust_string(&tool.result_contract), pdigest, escape_rust_string(tool.description.as_deref().expect("validated universal tool"))));
            } else {
                profile_rows.push(format!("    (\n        \"{}\",\n        \"{}\",\n        \"{}\",\n        \"{}\",\n        \"{}\",\n    ),", escape_rust_string(&tool.profile), escape_rust_string(&tool.name), escape_rust_string(&artifact.schema), escape_rust_string(&tool.result_contract), pdigest));
            }
        }
    }
    submit_rows.sort();
    profile_rows.sort();
    universal_rows.sort();
    rust.push_str(&format!(
        "\npub const SUBMIT_TOOLS: [(&str, &str, &str); {}] = [\n{}\n];\n",
        submit_rows.len(),
        submit_rows.join("\n")
    ));
    rust.push_str(&format!(
        "\npub const TERMINAL_PROFILES: [(&str, &str, &str, &str, &str); {}] = [\n{}\n];\n",
        profile_rows.len(),
        profile_rows.join("\n")
    ));
    rust.push_str(&format!(
        "\npub const UNIVERSAL_CHILD_TOOLS: [(&str, &str, &str, &str, &str, &str); {}] = [\n{}\n];\n",
        universal_rows.len(),
        universal_rows.join("\n")
    ));
    Ok(())
}

fn emit_frame_unions(ts: &mut String, frame_names: &[(String, String, String)]) {
    for (alias, direction) in [
        ("HostToCoreFrame", "host-to-core"),
        ("CoreToHostFrame", "core-to-host"),
    ] {
        let union = frame_names
            .iter()
            .filter(|(d, _, _)| d == direction)
            .map(|(_, kind, name)| {
                format!(
                    "{{ v: 1; id: number; kind: \"{}\"; payload: {} }}",
                    escape_ts_string(kind),
                    name
                )
            })
            .collect::<Vec<_>>()
            .join(" | ");
        ts.push_str(&format!("export type {alias} = {union};\n"));
    }
}

fn emit_tagged_union(
    rust: &mut String,
    ts: &mut String,
    ty_name: &str,
    doc: &str,
    tag: &str,
    variants: &[Item],
) {
    rust.push_str(&rust_doc(doc));
    rust.push_str("#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\n");
    rust.push_str(&format!(
        "#[serde(tag = \"{}\", deny_unknown_fields)]\npub enum {ty_name} {{\n",
        escape_rust_string(tag)
    ));
    ts.push_str(&format!("export type {ty_name} =\n"));
    for variant in variants {
        let value = variant.variant.as_deref().expect("validated tagged union");
        rust.push_str(&format!(
            "    #[serde(rename = \"{}\")]\n    {} {{\n",
            escape_rust_string(value),
            variant_name(&variant.name)
        ));
        ts.push_str(&format!("  | {{\n    {}: \"{}\";\n", quote_ts_key(tag), escape_ts_string(value)));
        for item in &variant.items {
            let (rust_ty, ts_ty) = member_types(item, ty_name)
                .expect("validated tagged-union member");
            let mut rust_member = String::new();
            let mut ts_member = String::new();
            emit_member(&mut rust_member, &mut ts_member, item, rust_ty, ts_ty);
            rust.push_str(&indent(&rust_member, "    "));
            ts.push_str(&indent(&ts_member, "    "));
        }
        rust.push_str("    },\n");
        ts.push_str("  }\n");
    }
    rust.push_str("}\n\n");
    ts.push_str(";\n\n");
}

fn emit_shape_tree(
    rust: &mut String,
    ts: &mut String,
    type_name: &str,
    doc: &str,
    items: &[Item],
    model_facing: bool,
) {
    emit_shape(rust, ts, type_name, doc, items, type_name, model_facing);
    for item in items
        .iter()
        .filter(|item| matches!(item.kind, ItemKind::Group | ItemKind::Record))
    {
        let nested = nested_name(type_name, item);
        emit_shape_tree(
            rust,
            ts,
            &nested,
            if item.kind == ItemKind::Group {
                "Nested generated object."
            } else {
                "Generated record item."
            },
            &item.items,
            model_facing,
        );
    }
}

fn emit_shape(
    rust: &mut String,
    ts: &mut String,
    ty_name: &str,
    doc: &str,
    items: &[Item],
    prefix: &str,
    model_facing: bool,
) {
    rust.push_str(&rust_doc(doc));
    rust.push_str("#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\n");
    if !model_facing {
        rust.push_str("#[serde(deny_unknown_fields)]\n");
    }
    rust.push_str(&format!("pub struct {ty_name} {{\n"));
    ts.push_str(&format!("export interface {ty_name} {{\n"));
    for item in items {
        if let Some((rust_ty, ts_ty)) = member_types(item, prefix) {
            emit_member(rust, ts, item, rust_ty, ts_ty);
        }
    }
    rust.push_str("}\n\n");
    ts.push_str("}\n\n");
}

fn member_types(item: &Item, prefix: &str) -> Option<(String, String)> {
    let pair = match item.kind {
        ItemKind::Field => (
            rust_field_type(&item.type_id, item.required, item.nullable),
            ts_field_type(&item.type_id, item.nullable),
        ),
        ItemKind::List => (
            wrap_required_nullable(
                &format!("Vec<{}>", rust_type_ref(&item.type_id)),
                item.required,
                item.nullable,
            ),
            maybe_nullable(&format!("{}[]", ts_type_ref(&item.type_id)), item.nullable),
        ),
        ItemKind::Group => {
            let ty = format!("{}{}", prefix, type_name(&item.name));
            (wrap_required_nullable(&ty, item.required, false), ty)
        }
        ItemKind::Record => return None,
    };
    Some(pair)
}

fn emit_member(rust: &mut String, ts: &mut String, item: &Item, rust_ty: String, ts_ty: String) {
    if let Some(doc) = &item.doc {
        rust.push_str(&indent(&rust_doc(doc), "    "));
    }
    rust.push_str(&format!(
        "    #[serde(rename = \"{}\")]\n",
        escape_rust_string(&item.name)
    ));
    if item.require_explicit_null {
        rust.push_str("    #[serde(deserialize_with = \"deserialize_required_nullable\")]\n");
    }
    if !item.required {
        rust.push_str("    #[serde(skip_serializing_if = \"Option::is_none\")]\n");
    }
    rust.push_str(&format!("    pub {}: {rust_ty},\n", field_name(&item.name)));
    ts.push_str(&format!(
        "  {}{}: {ts_ty};\n",
        quote_ts_key(&item.name),
        if item.required { "" } else { "?" }
    ));
}

pub fn emit_tool_schemas(contracts: &Contracts) -> Result<String> {
    let mut out = format!(
        "// {GENERATED_MARKER}\n\nimport type {{ TSchema }} from \"typebox\";\n\nexport interface ToolSchemaDescriptor {{\n  boundary_id: string;\n  schema_digest: string;\n  parameters: TSchema;\n}}\n\n"
    );
    let enum_values = enum_map(contracts);
    let shapes = schema_items_by_name(contracts);
    let mut descriptors = Vec::new();
    for artifact in contracts
        .artifacts
        .iter()
        .filter(|artifact| {
            artifact.model_produced
                && artifact.submit_tools.iter().any(|tool| !tool.universal)
        })
    {
        let default_closed = artifact
            .submit_tools
            .iter()
            .find(|tool| !tool.universal)
            .is_some_and(|tool| tool.closed);
        let mut closed_modes = vec![default_closed];
        if artifact
            .submit_tools
            .iter()
            .filter(|tool| !tool.universal)
            .any(|tool| tool.closed != default_closed)
        {
            closed_modes.push(!default_closed);
        }
        let mut schema_names = BTreeMap::new();
        for closed in closed_modes {
            let suffix = if closed == default_closed {
                ""
            } else if closed {
                "_CLOSED"
            } else {
                "_OPEN"
            };
            let schema = json_schema_for_items(&artifact.items, &shapes, &enum_values, closed)?;
            let schema_json = serde_json::to_string_pretty(&schema)
                .map_err(|error| Error::input(format!("json schema emit failed: {error}")))?;
            let digest = sha256_hex(json_string(&schema, "json schema digest")?.as_bytes());
            let const_name = format!("{}{suffix}_TOOL_PARAMETERS", screaming_name(&artifact.name));
            let digest_name = format!(
                "{}{suffix}_TOOL_SCHEMA_DIGEST",
                screaming_name(&artifact.name)
            );
            out.push_str(&format!(
                "export const {const_name} = {schema_json} as TSchema;\n"
            ));
            out.push_str(&format!("export const {digest_name} = \"{digest}\";\n\n"));
            schema_names.insert(closed, (const_name, digest_name));
        }
        let (const_name, digest_name) = schema_names
            .get(&default_closed)
            .cloned()
            .ok_or_else(|| Error::input("default terminal schema was not generated"))?;
        let tools = artifact
            .submit_tools
            .iter()
            .filter(|tool| !tool.universal)
            .map(|tool| {
                let (parameters, digest) = schema_names
                    .get(&tool.closed)
                    .cloned()
                    .ok_or_else(|| Error::input("terminal profile schema was not generated"))?;
                Ok((tool.clone(), parameters, digest))
            })
            .collect::<Result<Vec<_>>>()?;
        descriptors.push((artifact.schema.clone(), const_name, digest_name, tools));
    }
    out.push_str("export const TERMINAL_TOOL_SCHEMAS = {\n");
    for (boundary, const_name, digest_name, _) in &descriptors {
        out.push_str(&format!("  \"{}\": {{ boundary_id: \"{}\", schema_digest: {digest_name}, parameters: {const_name} }},\n", escape_ts_string(boundary), escape_ts_string(boundary)));
    }
    out.push_str("} as const satisfies Record<string, ToolSchemaDescriptor>;\n\nexport const PLANNING_TOOL_SCHEMAS = Object.fromEntries(Object.entries(TERMINAL_TOOL_SCHEMAS).filter(([boundary]) => boundary.startsWith(\"planning.\"))) as Record<string, ToolSchemaDescriptor>;\n\n");
    let mut rows = descriptors.iter().flat_map(|(boundary, _, _, tools)| {
        tools.iter().map(move |(tool, params, digest)| format!("  {{ profile_id: \"{}\", name: \"{}\", label: \"{}\", boundary_id: \"{}\", result_contract: \"{}\", schema_digest: {digest}, parameters: {params} }},", escape_ts_string(&tool.profile), escape_ts_string(&tool.name), escape_ts_string(&tool.label), escape_ts_string(boundary), escape_ts_string(&tool.result_contract)))
    }).collect::<Vec<_>>();
    rows.sort();
    out.push_str(&format!("export interface SubmitToolDescriptor {{\n  profile_id: string;\n  name: string;\n  label: string;\n  boundary_id: string;\n  result_contract: string;\n  schema_digest: string;\n  parameters: TSchema;\n}}\n\nexport const SUBMIT_TOOLS: readonly SubmitToolDescriptor[] = [\n{}\n] as const;\n", rows.join("\n")));
    emit_universal_child_tools(&mut out, contracts, &shapes, &enum_values)?;
    Ok(out)
}

const CHILD_CONTROL_PLACEHOLDER_SENTINEL: &str = "__autopilot_child_control_placeholder__:";

#[derive(Debug)]
struct PlaceholderTemplate {
    value: JsonValue,
    slot: Option<String>,
}

fn emit_child_control_bridge(contracts: &Contracts) -> Result<String> {
    let enums = enum_map(contracts);
    let shapes = schema_items_by_name(contracts);
    let mut rows = Vec::new();
    let mut terminal_profiles = 0usize;
    for artifact in &contracts.artifacts {
        if !artifact.model_produced {
            continue;
        }
        for tool in &artifact.submit_tools {
            let template = placeholder_for_items(&artifact.items, &shapes, &enums)?;
            let slot = template.slot.ok_or_else(|| {
                Error::input(format!(
                    "child-control placeholder has no nonce slot for profile `{}`",
                    tool.profile
                ))
            })?;
            let parameters = json_schema_for_items(&artifact.items, &shapes, &enums, tool.closed)?;
            let schema_digest = sha256_hex(
                json_string(&parameters, "child-control schema digest")?.as_bytes(),
            );
            validate_child_control_placeholder(
                &tool.profile,
                &template.value,
                &slot,
                &parameters,
            )?;
            if !tool.universal {
                terminal_profiles += 1;
            }
            rows.push(json!({
                "profile_id": tool.profile,
                "tool_name": tool.name,
                "kind": if tool.universal { "blocked" } else { "submit" },
                "boundary_id": artifact.schema,
                "result_contract": tool.result_contract,
                "schema_digest": schema_digest,
                "placeholder_pointer": slot,
                "placeholder": template.value,
            }));
        }
    }
    rows.sort_by(|left, right| left["profile_id"].as_str().cmp(&right["profile_id"].as_str()));
    require(
        terminal_profiles == 14,
        "child-control terminal profile metadata count drift; expected 14",
    )?;
    require(
        rows.len() == 15,
        "child-control placeholder metadata count drift; expected 15",
    )?;
    let metadata = pretty_json(&JsonValue::Array(rows), "child-control bridge metadata")?;
    let mut out = r#"// @generated by codegen

import { randomBytes } from "node:crypto";

import type { ChildControlRequest, ChildControlResponse } from "./index.ts";

export const CHILD_CONTROL_PLACEHOLDER_SENTINEL = "__autopilot_child_control_placeholder__:";
export const CHILD_CONTROL_TERMINAL_PROFILE_COUNT = 14;
export const CHILD_CONTROL_PLACEHOLDER_SCHEMA_VALIDATED_COUNT = 15;

export type ChildControlKind = "submit" | "blocked";
type JsonTree = null | boolean | number | string | readonly JsonTree[] | { readonly [key: string]: JsonTree };

export interface ChildControlToolMetadata {
  readonly profile_id: string;
  readonly tool_name: string;
  readonly kind: ChildControlKind;
  readonly boundary_id: string;
  readonly result_contract: string;
  readonly schema_digest: string;
  readonly placeholder_pointer: string;
  readonly placeholder: JsonTree;
}

export const CHILD_CONTROL_TOOL_METADATA = "#.to_owned();
    out.push_str(&metadata);
    out.push_str(" as const satisfies readonly ChildControlToolMetadata[];");
    out.push_str(r#"

export interface ChildControlBridgeBinding {
  readonly token: string;
  readonly run_id: string;
  readonly assignment_id: string;
  readonly attempt: number;
}

export interface ChildControlBridgeTransport {
  request(request: ChildControlRequest): Promise<ChildControlResponse>;
}

export interface ChildControlBridge {
  prepareArguments(profileId: string, rawPayload: unknown): Record<string, unknown>;
  execute(toolCallId: string, placeholder: unknown): Promise<ChildControlResponse>;
}

export class ChildControlBridgeProtocolError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ChildControlBridgeProtocolError";
  }
}

const PLACEHOLDER_TOKEN: unique symbol = Symbol("autopilot.child-control.placeholder");
type PlaceholderObject = Record<PropertyKey, unknown>;
type PendingCall = {
  readonly metadata: ChildControlToolMetadata;
  readonly rawPayload: unknown;
  readonly placeholder: PlaceholderObject;
  readonly token: object;
};

export function createChildControlBridge(
  binding: ChildControlBridgeBinding,
  transport: ChildControlBridgeTransport,
): ChildControlBridge {
  const pending = new Map<string, PendingCall>();
  const usedToolCallIds = new Set<string>();

  return {
    prepareArguments(profileId, rawPayload) {
      const metadata = CHILD_CONTROL_TOOL_METADATA.find((row) => row.profile_id === profileId);
      if (metadata === undefined) {
        throw new ChildControlBridgeProtocolError(`unknown child-control profile ${JSON.stringify(profileId)}`);
      }
      const nonce = randomBytes(32).toString("hex");
      const placeholder = structuredClone(metadata.placeholder) as PlaceholderObject;
      setPointer(placeholder, metadata.placeholder_pointer, `${CHILD_CONTROL_PLACEHOLDER_SENTINEL}${nonce}`);
      const token = {};
      Object.defineProperty(placeholder, PLACEHOLDER_TOKEN, {
        configurable: false,
        enumerable: false,
        value: token,
        writable: false,
      });
      pending.set(nonce, {
        metadata,
        rawPayload: structuredClone(rawPayload),
        placeholder,
        token,
      });
      return placeholder as Record<string, unknown>;
    },

    async execute(toolCallId, placeholder) {
      const holder = asPlaceholderObject(placeholder);
      const token = holder[PLACEHOLDER_TOKEN];
      if (token === null || typeof token !== "object") {
        throw new ChildControlBridgeProtocolError("child-control placeholder token is absent");
      }
      const nonce = placeholderNonce(holder);
      if (nonce === undefined) {
        throw new ChildControlBridgeProtocolError("child-control placeholder is unknown or already consumed");
      }
      const call = pending.get(nonce);
      if (call === undefined || call.placeholder !== holder || call.token !== token) {
        throw new ChildControlBridgeProtocolError("child-control placeholder is unknown or already consumed");
      }
      pending.delete(nonce);
      const expected = structuredClone(call.metadata.placeholder) as PlaceholderObject;
      setPointer(expected, call.metadata.placeholder_pointer, `${CHILD_CONTROL_PLACEHOLDER_SENTINEL}${nonce}`);
      if (!sameJsonShape(holder, expected) || usedToolCallIds.has(toolCallId)) {
        throw new ChildControlBridgeProtocolError("child-control placeholder shape or tool-call correlation mismatch");
      }
      usedToolCallIds.add(toolCallId);
      return transport.request({
        schema: "autopilot.child_control_request.v1",
        request_id: randomBytes(32).toString("hex"),
        token: binding.token,
        run_id: binding.run_id,
        assignment_id: binding.assignment_id,
        attempt: binding.attempt,
        tool_call_id: toolCallId,
        kind: call.metadata.kind,
        tool_name: call.metadata.tool_name,
        profile_id: call.metadata.profile_id,
        raw_payload: call.rawPayload,
      });
    },
  };
}

function asPlaceholderObject(value: unknown): PlaceholderObject {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new ChildControlBridgeProtocolError("child-control placeholder is not an object");
  }
  return value as PlaceholderObject;
}

function placeholderNonce(value: PlaceholderObject): string | undefined {
  const marker = findPlaceholderMarker(value);
  return marker?.startsWith(CHILD_CONTROL_PLACEHOLDER_SENTINEL)
    ? marker.slice(CHILD_CONTROL_PLACEHOLDER_SENTINEL.length)
    : undefined;
}

function findPlaceholderMarker(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const marker = findPlaceholderMarker(item);
      if (marker?.startsWith(CHILD_CONTROL_PLACEHOLDER_SENTINEL)) return marker;
    }
    return undefined;
  }
  if (value !== null && typeof value === "object") {
    for (const item of Object.values(value)) {
      const marker = findPlaceholderMarker(item);
      if (marker?.startsWith(CHILD_CONTROL_PLACEHOLDER_SENTINEL)) return marker;
    }
  }
  return undefined;
}

function setPointer(value: PlaceholderObject, pointer: string, marker: string): void {
  const parts = pointer.slice(1).split("/").map((part) => part.replaceAll("~1", "/").replaceAll("~0", "~"));
  let current: unknown = value;
  for (const [index, part] of parts.entries()) {
    const last = index === parts.length - 1;
    if (Array.isArray(current)) {
      const offset = Number(part);
      if (!Number.isInteger(offset) || current[offset] === undefined) {
        throw new ChildControlBridgeProtocolError("generated child-control placeholder pointer drift");
      }
      if (last) current[offset] = marker;
      else current = current[offset];
    } else if (current !== null && typeof current === "object") {
      const record = current as Record<string, unknown>;
      if (!(part in record)) throw new ChildControlBridgeProtocolError("generated child-control placeholder pointer drift");
      if (last) record[part] = marker;
      else current = record[part];
    } else {
      throw new ChildControlBridgeProtocolError("generated child-control placeholder pointer drift");
    }
  }
}

function sameJsonShape(left: unknown, right: unknown): boolean {
  if (left === right) return true;
  if (Array.isArray(left) || Array.isArray(right)) {
    return Array.isArray(left)
      && Array.isArray(right)
      && left.length === right.length
      && left.every((item, index) => sameJsonShape(item, right[index]));
  }
  if (left !== null && right !== null && typeof left === "object" && typeof right === "object") {
    const leftRecord = left as Record<string, unknown>;
    const rightRecord = right as Record<string, unknown>;
    const leftKeys = Object.keys(leftRecord).sort();
    const rightKeys = Object.keys(rightRecord).sort();
    return leftKeys.length === rightKeys.length
      && leftKeys.every((key, index) => key === rightKeys[index] && sameJsonShape(leftRecord[key], rightRecord[key]));
  }
  return false;
}
"#);
    Ok(out)
}

fn validate_child_control_placeholder(
    profile: &str,
    template: &JsonValue,
    slot: &str,
    schema: &JsonValue,
) -> Result<()> {
    let mut placeholder = template.clone();
    let marker = format!("{CHILD_CONTROL_PLACEHOLDER_SENTINEL}{}", "0".repeat(64));
    set_placeholder_marker(&mut placeholder, slot, &marker)?;
    validate_placeholder_schema(schema, &placeholder, profile, "")
}

fn set_placeholder_marker(value: &mut JsonValue, pointer: &str, marker: &str) -> Result<()> {
    let segments = pointer
        .strip_prefix('/')
        .ok_or_else(|| Error::input("child-control placeholder pointer must be absolute"))?
        .split('/')
        .map(|segment| segment.replace("~1", "/").replace("~0", "~"))
        .collect::<Vec<_>>();
    let mut current = value;
    for (index, segment) in segments.iter().enumerate() {
        let last = index + 1 == segments.len();
        current = match current {
            JsonValue::Object(object) => object.get_mut(segment).ok_or_else(|| {
                Error::input("generated child-control placeholder pointer drift")
            })?,
            JsonValue::Array(items) => {
                let offset = segment.parse::<usize>().map_err(|_| {
                    Error::input("generated child-control placeholder pointer drift")
                })?;
                items.get_mut(offset).ok_or_else(|| {
                    Error::input("generated child-control placeholder pointer drift")
                })?
            }
            _ => return Err(Error::input("generated child-control placeholder pointer drift")),
        };
        if last {
            *current = JsonValue::String(marker.to_owned());
        }
    }
    Ok(())
}

fn validate_placeholder_schema(
    schema: &JsonValue,
    value: &JsonValue,
    profile: &str,
    pointer: &str,
) -> Result<()> {
    if let Some(variants) = schema.get("anyOf").and_then(JsonValue::as_array) {
        if variants
            .iter()
            .any(|variant| validate_placeholder_schema(variant, value, profile, pointer).is_ok())
        {
            return Ok(());
        }
        return Err(placeholder_schema_error(profile, pointer, "matches no anyOf branch"));
    }
    if let Some(constant) = schema.get("const") {
        if constant != value {
            return Err(placeholder_schema_error(profile, pointer, "does not match const"));
        }
    }
    if let Some(values) = schema.get("enum").and_then(JsonValue::as_array) {
        if !values.iter().any(|candidate| candidate == value) {
            return Err(placeholder_schema_error(profile, pointer, "does not match enum"));
        }
    }
    match schema.get("type").and_then(JsonValue::as_str) {
        None => Ok(()),
        Some("string") => {
            let text = value.as_str().ok_or_else(|| {
                placeholder_schema_error(profile, pointer, "is not a string")
            })?;
            validate_schema_length(schema, text.chars().count(), profile, pointer, "Length")
        }
        Some("integer") => {
            if value.as_u64().is_some() {
                Ok(())
            } else {
                Err(placeholder_schema_error(profile, pointer, "is not a non-negative integer"))
            }
        }
        Some("boolean") if value.is_boolean() => Ok(()),
        Some("boolean") => Err(placeholder_schema_error(profile, pointer, "is not boolean")),
        Some("object") => validate_placeholder_object(schema, value, profile, pointer),
        Some("array") => validate_placeholder_array(schema, value, profile, pointer),
        Some(other) => Err(placeholder_schema_error(
            profile,
            pointer,
            &format!("uses unsupported generator schema type {other}"),
        )),
    }
}

fn validate_schema_length(
    schema: &JsonValue,
    length: usize,
    profile: &str,
    pointer: &str,
    label: &str,
) -> Result<()> {
    if schema
        .get("minLength")
        .and_then(JsonValue::as_u64)
        .is_some_and(|min| length < min as usize)
        || schema
            .get("minItems")
            .and_then(JsonValue::as_u64)
            .is_some_and(|min| length < min as usize)
    {
        return Err(placeholder_schema_error(profile, pointer, &format!("{label} is below minimum")));
    }
    if schema
        .get("maxLength")
        .and_then(JsonValue::as_u64)
        .is_some_and(|max| length > max as usize)
        || schema
            .get("maxItems")
            .and_then(JsonValue::as_u64)
            .is_some_and(|max| length > max as usize)
    {
        return Err(placeholder_schema_error(profile, pointer, &format!("{label} exceeds maximum")));
    }
    Ok(())
}

fn validate_placeholder_object(
    schema: &JsonValue,
    value: &JsonValue,
    profile: &str,
    pointer: &str,
) -> Result<()> {
    let object = value
        .as_object()
        .ok_or_else(|| placeholder_schema_error(profile, pointer, "is not an object"))?;
    let properties = schema
        .get("properties")
        .and_then(JsonValue::as_object)
        .ok_or_else(|| placeholder_schema_error(profile, pointer, "has no properties"))?;
    for required in schema
        .get("required")
        .and_then(JsonValue::as_array)
        .into_iter()
        .flatten()
    {
        let name = required
            .as_str()
            .ok_or_else(|| placeholder_schema_error(profile, pointer, "has non-string required key"))?;
        if !object.contains_key(name) {
            return Err(placeholder_schema_error(profile, pointer, "is missing required key"));
        }
    }
    if schema.get("additionalProperties") == Some(&JsonValue::Bool(false))
        && object.keys().any(|key| !properties.contains_key(key))
    {
        return Err(placeholder_schema_error(profile, pointer, "contains an unknown key"));
    }
    for (name, child) in object {
        if let Some(child_schema) = properties.get(name) {
            validate_placeholder_schema(
                child_schema,
                child,
                profile,
                &format!("{pointer}/{name}"),
            )?;
        }
    }
    Ok(())
}

fn validate_placeholder_array(
    schema: &JsonValue,
    value: &JsonValue,
    profile: &str,
    pointer: &str,
) -> Result<()> {
    let items = value
        .as_array()
        .ok_or_else(|| placeholder_schema_error(profile, pointer, "is not an array"))?;
    validate_schema_length(schema, items.len(), profile, pointer, "item count")?;
    let item_schema = schema
        .get("items")
        .ok_or_else(|| placeholder_schema_error(profile, pointer, "has no item schema"))?;
    for (index, item) in items.iter().enumerate() {
        validate_placeholder_schema(item_schema, item, profile, &format!("{pointer}/{index}"))?;
    }
    if schema.get("uniqueItems") == Some(&JsonValue::Bool(true)) {
        let mut unique = std::collections::BTreeSet::new();
        for item in items {
            let canonical = json_string(item, "placeholder unique item")?;
            if !unique.insert(canonical) {
                return Err(placeholder_schema_error(profile, pointer, "has duplicate items"));
            }
        }
    }
    Ok(())
}

fn placeholder_schema_error(profile: &str, pointer: &str, reason: &str) -> Error {
    Error::input(format!(
        "child-control placeholder for profile `{profile}` fails generated TypeBox-equivalent schema at `{pointer}`: {reason}"
    ))
}

fn placeholder_for_items(
    items: &[Item],
    shapes: &BTreeMap<String, Vec<Item>>,
    enums: &BTreeMap<&str, Vec<String>>,
) -> Result<PlaceholderTemplate> {
    let mut value = JsonMap::new();
    let mut slot = None;
    for item in items {
        if item.kind == ItemKind::Record || !item.required {
            continue;
        }
        let template = placeholder_for_item(item, shapes, enums)?;
        if slot.is_none() {
            slot = template
                .slot
                .as_deref()
                .map(|child| format!("/{}{}", pointer_segment(&item.name), child));
        }
        value.insert(item.name.clone(), template.value);
    }
    Ok(PlaceholderTemplate {
        value: JsonValue::Object(value),
        slot,
    })
}

fn placeholder_for_item(
    item: &Item,
    shapes: &BTreeMap<String, Vec<Item>>,
    enums: &BTreeMap<&str, Vec<String>>,
) -> Result<PlaceholderTemplate> {
    match item.kind {
        ItemKind::Field => {
            if let Some(constant) = &item.constant {
                return Ok(PlaceholderTemplate {
                    value: placeholder_constant(&item.type_id, constant)?,
                    slot: None,
                });
            }
            placeholder_for_type(&item.type_id, item.max_bytes, shapes, enums)
        }
        ItemKind::List => {
            let template = placeholder_for_type(&item.type_id, item.item_max_bytes, shapes, enums)?;
            Ok(PlaceholderTemplate {
                value: JsonValue::Array(vec![template.value]),
                slot: template.slot.map(|child| format!("/0{child}")),
            })
        }
        ItemKind::Group => placeholder_for_items(&item.items, shapes, enums),
        ItemKind::Record => Err(Error::input("record cannot be a placeholder property")),
    }
}

fn placeholder_for_type(
    type_id: &str,
    max_bytes: Option<u64>,
    shapes: &BTreeMap<String, Vec<Item>>,
    enums: &BTreeMap<&str, Vec<String>>,
) -> Result<PlaceholderTemplate> {
    if let Some(values) = enums.get(type_id) {
        return Ok(PlaceholderTemplate {
            value: JsonValue::String(
                values
                    .first()
                    .cloned()
                    .ok_or_else(|| Error::input(format!("empty enum `{type_id}`")))?,
            ),
            slot: None,
        });
    }
    if let Some(items) = shapes.get(type_id) {
        return placeholder_for_items(items, shapes, enums);
    }
    let (value, slot) = match type_id {
        "bool" => (JsonValue::Bool(false), None),
        "u8" | "u32" | "u64" => (JsonValue::from(0_u64), None),
        "object" | "json" | "json-value" | "control_observation" => {
            (JsonValue::Object(JsonMap::new()), None)
        }
        _ => {
            let can_hold_nonce = max_bytes.is_none_or(|max| {
                max >= (CHILD_CONTROL_PLACEHOLDER_SENTINEL.len() + 64) as u64
            });
            (
                JsonValue::String("x".to_owned()),
                if can_hold_nonce { Some(String::new()) } else { None },
            )
        }
    };
    Ok(PlaceholderTemplate { value, slot })
}

fn placeholder_constant(type_id: &str, value: &str) -> Result<JsonValue> {
    match type_id {
        "bool" => value
            .parse::<bool>()
            .map(JsonValue::Bool)
            .map_err(|error| Error::input(format!("invalid placeholder bool constant: {error}"))),
        "u8" | "u32" | "u64" => value
            .parse::<u64>()
            .map(JsonValue::from)
            .map_err(|error| Error::input(format!("invalid placeholder integer constant: {error}"))),
        _ => Ok(JsonValue::String(value.to_owned())),
    }
}

fn pointer_segment(value: &str) -> String {
    value.replace('~', "~0").replace('/', "~1")
}

fn emit_universal_child_tools(
    out: &mut String,
    contracts: &Contracts,
    shapes: &BTreeMap<String, Vec<Item>>,
    enums: &BTreeMap<&str, Vec<String>>,
) -> Result<()> {
    let mut rows = Vec::new();
    for artifact in &contracts.artifacts {
        if !artifact.model_produced {
            continue;
        }
        for tool in artifact.submit_tools.iter().filter(|tool| tool.universal) {
            let schema = json_schema_for_items(&artifact.items, shapes, enums, tool.closed)?;
            let schema_json = serde_json::to_string_pretty(&schema)
                .map_err(|error| Error::input(format!("json schema emit failed: {error}")))?;
            let digest = sha256_hex(json_string(&schema, "universal tool schema digest")?.as_bytes());
            let const_name = format!("{}_TOOL_PARAMETERS", screaming_name(&artifact.name));
            let digest_name = format!("{}_TOOL_SCHEMA_DIGEST", screaming_name(&artifact.name));
            out.push_str(&format!("\nexport const {const_name} = {schema_json} as TSchema;\n"));
            out.push_str(&format!("export const {digest_name} = \"{digest}\";\n"));
            rows.push(format!(
                "  {{ profile_id: \"{}\", name: \"{}\", label: \"{}\", description: \"{}\", boundary_id: \"{}\", result_contract: \"{}\", schema_digest: {digest_name}, parameters: {const_name} }},",
                escape_ts_string(&tool.profile),
                escape_ts_string(&tool.name),
                escape_ts_string(&tool.label),
                escape_ts_string(tool.description.as_deref().expect("validated universal tool")),
                escape_ts_string(&artifact.schema),
                escape_ts_string(&tool.result_contract),
            ));
        }
    }
    rows.sort();
    out.push_str("\nexport interface UniversalChildToolDescriptor extends SubmitToolDescriptor {\n  description: string;\n}\n\n");
    out.push_str(&format!(
        "export const UNIVERSAL_CHILD_TOOLS: readonly UniversalChildToolDescriptor[] = [\n{}\n] as const;\n",
        rows.join("\n")
    ));
    out.push_str("export const BLOCKED_REPORT_TOOL = UNIVERSAL_CHILD_TOOLS[0]!;\n");
    Ok(())
}

pub fn emit_child_extension() -> String {
    // "../../" climbs from src/generated/ to the package root, then the entry.
    let runtime = format!("../../{CHILD_RUNTIME_ENTRY}");
    format!(
        r#"// {GENERATED_MARKER}
// Child add-on digest covers this wrapper plus {runtime}.
import type {{ ExtensionAPI }} from "@earendil-works/pi-coding-agent";
import {{ CHILD_RECEIPT_ENTRY, runAutopilotChild }} from "{runtime}";
import {{ SUBMIT_TOOLS }} from "./tool-schemas.ts";
export {{ CHILD_RECEIPT_ENTRY }};
export default function(pi: ExtensionAPI): void {{ runAutopilotChild(pi, SUBMIT_TOOLS, import.meta.url); }}
"#
    )
}

fn sha256_hex(data: &[u8]) -> String {
    Sha256::digest(data)
        .iter()
        .fold(String::new(), |mut out, byte| {
            out.push_str(&format!("{byte:02x}"));
            out
        })
}

fn enum_map(contracts: &Contracts) -> BTreeMap<&str, Vec<String>> {
    contracts
        .enums
        .iter()
        .map(|entry| (entry.name.as_str(), entry.values.clone()))
        .collect()
}

fn emit_prompt(name: &str, admits: &str) -> String {
    format!("<!-- {GENERATED_MARKER} -->\n# {name}\n\n{admits}\n")
}
fn frame_type_name(frame: &Frame) -> String {
    format!(
        "{}{}Payload",
        if frame.direction == "host-to-core" {
            "HostToCore"
        } else {
            "CoreToHost"
        },
        type_name(&frame.kind)
    )
}
fn nested_name(prefix: &str, item: &Item) -> String {
    if item.kind == ItemKind::Group {
        format!("{}{}", prefix, type_name(&item.name))
    } else {
        type_name(&item.name)
    }
}
fn rust_doc(doc: &str) -> String {
    doc.lines().map(|line| format!("/// {line}\n")).collect()
}
fn indent(text: &str, prefix: &str) -> String {
    text.lines()
        .map(|line| format!("{prefix}{line}\n"))
        .collect()
}
fn screaming_name(input: &str) -> String {
    input
        .replace(|c: char| !c.is_ascii_alphanumeric(), "_")
        .to_ascii_uppercase()
}
